function initCreatorNavHistory(){
  creatorNavCollectionRunnerRender();
  creatorNavHistoryRecord(creatorNavHistoryUrl(),creatorNavHistoryCaptureState());
  creatorNavHistoryRestorePending();
  setTimeout(()=>{
    creatorNavHistoryRecord(creatorNavHistoryUrl(),creatorNavHistoryCaptureState());
    updateCreatorNavHistoryControls();
  },300);
  updateCreatorNavHistoryControls();
  if(document.documentElement.dataset.creatorNavHistoryBound)return;
  document.documentElement.dataset.creatorNavHistoryBound="1";
  document.addEventListener("click",event=>{
    const link=event.target.closest?.("a[href]");
    if(!link||event.defaultPrevented||event.button!==0)return;
    if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
    const raw=link.getAttribute("href");
    if(!raw||raw.startsWith("#")||raw.startsWith("mailto:")||raw.startsWith("tel:"))return;
    try{
      const next=new URL(raw,location.href);
      if(next.origin!==location.origin)return;
      const currentUrl=creatorNavHistoryUrl();
      const rows=creatorNavHistoryRead();
      if(rows.length&&rows[rows.length-1].url===currentUrl){
        rows[rows.length-1].state=creatorNavHistoryCaptureState();
        creatorNavHistoryWrite(rows);
      }
      creatorNavHistoryRecord(next.pathname+next.search+next.hash,{});
    }catch{}
  },true);
}

initCreatorNavHistory();

